props.pageLoadAction:
(
  $time := $moment();
  $thirtyDaysAgo := $moment().subtract(30, 'days').toISOString();

  $statement := 'query GetAlarmCounts($where: AlarmWhereInput) {
    alarm(where: $where) {
      edges {
        node {
          alarmStateId
          _aggregate {
            id {
              count
            }
          }
        }
      }
    }
  }';

  $variables := {
    'where': {
      'triggeredAt': {
        '_gte': $thirtyDaysAgo
      }
    }
  };

  $result := $query({'statement': $statement, 'variables': $variables});
  $alarmGroups := $result.alarm.edges.node;

  $activeCount := $alarmGroups[alarmStateId = 'ACTIVE']._aggregate.id.count ? $alarmGroups[alarmStateId = 'ACTIVE']._aggregate.id.count : 0;
  $acknowledgedCount := $alarmGroups[alarmStateId = 'ACTIVE_ACK']._aggregate.id.count ? $alarmGroups[alarmStateId = 'ACTIVE_ACK']._aggregate.id.count : 0;

  $clearedUnackCount := $alarmGroups[alarmStateId = 'CLEARED_UNACK']._aggregate.id.count ? $alarmGroups[alarmStateId = 'CLEARED_UNACK']._aggregate.id.count : 0;
  $clearedAckCount := $alarmGroups[alarmStateId = 'CLEARED_ACK']._aggregate.id.count ? $alarmGroups[alarmStateId = 'CLEARED_ACK']._aggregate.id.count : 0;
  $clearedCount := $clearedUnackCount + $clearedAckCount;

  $totalCount := $sum($alarmGroups._aggregate.id.count);

  $alarmRatePerHour := $round($totalCount / (30 * 24), 1);
  $alarmRateColor := $alarmRatePerHour < 10 ? '#4CAF50' : '#F44336';

  $context := {
    'activeCount': $activeCount,
    'acknowledgedCount': $acknowledgedCount,
    'clearedCount': $clearedCount,
    'totalCount': $totalCount,
    'alarmRatePerHour': $alarmRatePerHour,
    'alarmRateColor': $alarmRateColor,
    'lastRefreshedAt': $moment($time).format('MM/DD/YYYY HH:mm:ss')
  };

  $components.Screen.fn.setContext($context);

  $context
)
